SELECT oi.id, oi.order_no as orderNo, oi.user_id as userId, oi.restaurant_id as restaurantId, r.name as restaurantName, oi.order_status as orderStatus, oi.total_amount as totalAmount, oi.remark, oi.create_time as createTime, oi.update_time as updateTime FROM order_info oi LEFT JOIN restaurant r ON oi.restaurant_id = r.id WHERE 1=1
AND oi.order_no LIKE CONCAT('%', #{orderNo}, '%')
AND oi.user_id = #{userId}
AND oi.restaurant_id = #{restaurantId}
AND oi.order_status = #{orderStatus}
ORDER BY oi.create_time DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM order_info
WHERE 1=1

    AND order_no LIKE CONCAT('%', #{orderNo}, '%')


    AND user_id = #{userId}


    AND restaurant_id = #{restaurantId}


    AND order_status = #{orderStatus}

SELECT DATE(create_time) as statDate, restaurant_id as restaurantId, COUNT(*) as orderCount, SUM(total_amount) as totalAmount, COUNT(DISTINCT user_id) as customerCount FROM order_info WHERE 1=1
AND restaurant_id = #{restaurantId}
AND DATE(create_time) >= #{startDate}
AND DATE(create_time) <= #{endDate}
GROUP BY DATE(create_time), restaurant_id ORDER BY statDate DESC

SELECT id
FROM restaurant
WHERE user_id = #{userId}
